[[[6,11,"<",66],[2,7,">=",14],[1,0,"<=",9]],[6*x+11*y<66,2*x+7*y>=14,1*x<=9],[11*x+6*y<66,7*x+2*y>=14,1*y<=9],[[-1,11,13,-1],[[6,11,66,1,1,0.96,5.81,1],[2,7,14,-1,0,1.02,1.96,2],[1,0,9,1,0,9.35,10.05,3]],[[11.0,0.0,0,0,0,0],[0.0,6.0,0,0,0,0],[7.0,0.0,0,0,0,0],[0.0,2.0,0,0,0,0],[9.0,0.0,0,0,0,0]],[4.7,2.12],2],"Graph with x from 0 to 12 and y from 0 to 10, grid every 1 unit. L1 is dashed, the line through (11, 0) and (0, 6); the side away from the origin is shaded. L2 is solid, the line through (7, 0) and (0, 2); the side containing the origin is shaded. L3 is solid, the vertical line x = 9; the side away from the origin is shaded. The parts with x less than 0 and y less than 0 are shaded. R is the clear region.",["Your sign includes the points on the line, but the line is dashed: its points do not belong to R.","Your sign leaves out the points on the line, but the line is solid: its points belong to R.","Your sign leaves out the points on the line, but the line is solid: its points belong to R."],[["(11, 0)","(0, 6)"],["(7, 0)","(0, 2)"],["(9, 0)","(9, 5)"]],"(5, 2)",["6x + 11y \\lt 66","2x + 7y \\ge 14","x \\le 9"],[[[11,0],[0,6]],[[7,0],[0,2]],[[9,0],[9,5]]]],
[[[5,9,"<=",45],[3,7,">=",21],[0,1,">",2]],[5*x+9*y<=45,3*x+7*y>=21,1*y>2],[9*x+5*y<=45,7*x+3*y>=21,1*x>2],[[-1,11,13,-1],[[5,9,45,1,0,0.96,4.81,1],[3,7,21,-1,0,0.99,2.87,2],[0,1,2,-1,1,12.25,2.15,3]],[[9.0,0.0,0,0,0,0],[0.0,5.0,0,0,0,0],[7.0,0.0,0,0,0,0],[0.0,3.0,0,0,0,0],[0.0,2.0,0,0,0,0]],[1.63,3.3],2],"Graph with x from 0 to 12 and y from 0 to 10, grid every 1 unit. L1 is solid, the line through (9, 0) and (0, 5); the side away from the origin is shaded. L2 is solid, the line through (7, 0) and (0, 3); the side containing the origin is shaded. L3 is dashed, the horizontal line y = 2; the side containing the origin is shaded. The parts with x less than 0 and y less than 0 are shaded. R is the clear region.",["Your sign leaves out the points on the line, but the line is solid: its points belong to R.","Your sign leaves out the points on the line, but the line is solid: its points belong to R.","Your sign includes the points on the line, but the line is dashed: its points do not belong to R."],[["(9, 0)","(0, 5)"],["(7, 0)","(0, 3)"],["(0, 2)","(6, 2)"]],"(2, 3)",["5x + 9y \\le 45","3x + 7y \\ge 21","y \\gt 2"],[[[9,0],[0,5]],[[7,0],[0,3]],[[0,2],[6,2]]]],
[[[9,10,"<=",90],[7,4,">",28],[1,0,"<",5]],[9*x+10*y<=90,7*x+4*y>28,1*x<5],[10*x+9*y<=90,4*x+7*y>28,1*y<5],[[-1,11,13,-1],[[9,10,90,1,0,0.87,8.68,1],[7,4,28,-1,1,0.7,6.54,2],[1,0,5,1,1,5.35,10.05,3]],[[10.0,0.0,0,0,0,0],[0.0,9.0,0,0,0,0],[4.0,0.0,0,0,0,0],[0.0,7.0,0,0,0,0],[5.0,0.0,0,0,0,0]],[2.5,4.3999999999999995],2],"Graph with x from 0 to 12 and y from 0 to 10, grid every 1 unit. L1 is solid, the line through (10, 0) and (0, 9); the side away from the origin is shaded. L2 is dashed, the line through (4, 0) and (0, 7); the side containing the origin is shaded. L3 is dashed, the vertical line x = 5; the side away from the origin is shaded. The parts with x less than 0 and y less than 0 are shaded. R is the clear region.",["Your sign leaves out the points on the line, but the line is solid: its points belong to R.","Your sign includes the points on the line, but the line is dashed: its points do not belong to R.","Your sign includes the points on the line, but the line is dashed: its points do not belong to R."],[["(10, 0)","(0, 9)"],["(4, 0)","(0, 7)"],["(5, 0)","(5, 5)"]],"(3, 4)",["9x + 10y \\le 90","7x + 4y \\gt 28","x \\lt 5"],[[[10,0],[0,9]],[[4,0],[0,7]],[[5,0],[5,5]]]]];
ix: 1+rand(10);
E: Q22L[ix];
ta1: E[2][1]; ta2: E[2][2]; ta3: E[2][3];
JB: E[4]; arl: E[5]; sty: E[6]; tp: E[7]; rp: E[8]; td: E[9]; tpm: E[10];
/* onl(q, P): is the point P on the boundary line of the inequality q? */
onl(q, P) := is(abs(subst([x = P[1], y = P[2]], lhs(q) - rhs(q))) < 1/10^6);
misl(q, k) := block([u: onl(q, tpm[k][1]), w: onl(q, tpm[k][2])],
  if u and w then "" elseif u then "Your boundary line passes through the first of these points but not the second."
  elseif w then "Your boundary line passes through the second of these points but not the first."
  else "Your boundary line passes through neither of them.");
ta3r: revq(ta3);
fl1: flipq(ta1); fl2: flipq(ta2); fl3: flipq(ta3);
st1: strq(ta1); st2: strq(ta2); st3: strq(ta3);
bo1: flipq(strq(ta1)); bo2: flipq(strq(ta2)); bo3: flipq(strq(ta3));
sw1: E[3][1];
ol3: if E[1][3][1] = 0 then subst([y = x], ta3) else subst([x = y], ta3);
